const items = $input.all();

if (!items.length) {
  return [{ json: { _isEmpty: true, overdueCount: 0 } }];
}

const nowMs = Date.now();

const lines = items.map(item => {
  const av = item.json;
  const deadlineMs = new Date(av.sla_deadline).getTime();
  const hoursOverdue = Math.max(1, Math.round((nowMs - deadlineMs) / 3600000));
  const overdueStr = hoursOverdue >= 48
    ? Math.floor(hoursOverdue / 24) + 'd ' + (hoursOverdue % 24) + 'h'
    : hoursOverdue + 'h';
  return '\u2022 *' + av.cve_id_str + '* \u2014 ' + av.asset_name
    + ' | ' + av.criticality_tier
    + ' | Score: ' + av.risk_score
    + ' | Overdue: ' + overdueStr
    + ' | Status: ' + av.alert_status;
}).join('\n');

const header = items.length === 1
  ? '\u26a0\ufe0f SLA Breach \u2014 1 overdue vulnerability'
  : '\u26a0\ufe0f SLA Breach \u2014 ' + items.length + ' overdue vulnerabilities';

const bodyText = lines.length <= 2990
  ? lines
  : lines.slice(0, 2990) + '\n_\u2026truncated_';

const slackPayload = JSON.stringify({
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: header, emoji: true }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: bodyText }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: 'VulnPatchNotifier Monitoring | ' + new Date().toISOString().slice(0, 19) + ' UTC'
        }
      ]
    }
  ]
});

return [{ json: { slackPayload, overdueCount: items.length, _isEmpty: false } }];
